26	std::string base64_encode(const std::string& input)
27	{
28	    static constexpr char table[] = "REDACTED/";
29	    std::string out;
30	    int value = 0;
31	    int bits = -6;
32	    for (unsigned char byte : input) {
33	        value = (value << 8) + byte;
34	        bits += 8;
35	        while (bits >= 0) { out.push_back(table[(value >> bits) & 0x3f]); bits -= 6; }
36	    }
37	    if (bits > -6) out.push_back(table[((value << 8) >> (bits + 8)) & 0x3f]);
38	    while (out.size() % 4) out.push_back('=');
39	    return out;
40	}
