42	std::string response_text(const json& response)
43	{
44	    if (response.contains("output_text") && response["output_text"].is_string())
45	        return response["output_text"].get<std::string>();
46	    for (const auto& output : response.value("output", json::array()))
47	        for (const auto& content : output.value("content", json::array()))
48	            if (content.value("type", "") == "output_text" && content.contains("text") && content["text"].is_string())
49	                return content["text"].get<std::string>();
50	    return {};
51	}
