53	RecognitionError http_error(unsigned status)
54	{
55	    if (status == 401 || status == 403)
56	        return {"authentication", "OpenAI could not authenticate the configured API key.", false};
57	    if (status == 429)
58	        return {"rate_limit", "OpenAI is busy or the configured account has reached its limit. Try again.", true};
59	    if (status >= 500)
60	        return {"provider", "OpenAI could not recognize the printer right now. Try again.", true};
61	    return {"request", "The printer recognition request was rejected.", false};
62	}
