161	RecognitionEvent OpenAIPrinterRecognition::parse(std::uint64_t generation, unsigned status,
162	                                                 const std::string& body) const
163	{
164	    RecognitionEvent event;
165	    event.generation = generation;
166	    if (status < 200 || status >= 300) { event.error = http_error(status); return event; }
167	    const json response = json::parse(body, nullptr, false);
168	    if (!response.is_object()) {
169	        event.error = RecognitionError{"malformed_response", "OpenAI returned an unreadable response.", true};
170	        return event;
171	    }
172	    const json recognized = json::parse(response_text(response), nullptr, false);
173	    if (!recognized.is_object()) {
174	        event.error = RecognitionError{"malformed_response", "OpenAI returned an unreadable recognition result.", true};
175	        return event;
176	    }
177	    RecognitionResult result;
178	    const std::string disposition = recognized.value("disposition", "no_match");
179	    result.disposition = disposition == "recognized" ? RecognitionDisposition::Recognized
180	                       : disposition == "ambiguous" ? RecognitionDisposition::Ambiguous
181	                                                    : RecognitionDisposition::NoMatch;
182	    if (recognized.contains("candidate_ids") && recognized["candidate_ids"].is_array())
183	        for (const auto& id : recognized["candidate_ids"])
184	            if (id.is_string()) result.candidate_ids.push_back(id.get<std::string>());
185	    result.evidence_summary = recognized.value("evidence_summary", "");
186	    result.assumption = recognized.value("assumption", "");
187	    // A missing confidence reads as uncertain, never as certain.
188	    if (recognized.contains("confidence") && recognized["confidence"].is_number())
189	        result.confidence = recognized["confidence"].get<double>();
190	    result.unresolved_correction = recognized.value("unresolved_correction", "");
191	    event.result = std::move(result);
192	    return event;
193	}
