195	std::optional<RecognitionEvent> OpenAIPrinterRecognition::poll()
196	{
197	    std::deque<HttpItem> incoming;
198	    {
199	        std::lock_guard<std::mutex> lock(m_mutex);
200	        incoming.swap(m_http);
201	    }
202	    for (HttpItem& item : incoming) {
203	        if (!m_busy || item.generation != m_generation) continue;
204	        if (item.event.kind == Agent::AgentHttpEvent::Kind::Data) m_body += item.event.data;
205	        else if (item.event.kind == Agent::AgentHttpEvent::Kind::Error) {
206	            m_busy = false;
207	            RecognitionEvent failure;
208	            failure.generation = item.generation;
209	            failure.error = item.event.status ? http_error(item.event.status)
210	                : RecognitionError{"network", "Could not reach OpenAI. Check the connection and try again.", true};
211	            m_events.push_back(std::move(failure));
212	        } else {
213	            m_busy = false;
214	            m_events.push_back(parse(item.generation, item.event.status, m_body));
215	        }
216	    }
217	    if (m_events.empty()) return std::nullopt;
218	    RecognitionEvent event = std::move(m_events.front());
219	    m_events.pop_front();
220	    return event;
221	}
