223	bool DeterministicPrinterRecognition::start(std::uint64_t generation, const PrinterEvidence& evidence,
224	                                            const std::vector<const PrinterCandidate*>& choices)
225	{
226	    RecognitionEvent event;
227	    event.generation = generation;
228	    RecognitionResult result;
229	    const std::string description = lowercase(evidence.description);
230	    const std::size_t match_at = description.find("\ncurrent match: ");
231	    const std::size_t correction_at = description.rfind("\ncorrection: ");
232	    const std::string correction = correction_at == std::string::npos
233	        ? std::string() : evidence.description.substr(correction_at + std::string("\ncorrection: ").size());
234	    // A nozzle size counts only where the user stated it: in the correction
235	    // when there is one, since the current-match line names the old variant.
236	    const std::string variant_text = correction_at == std::string::npos ? description : description.substr(correction_at);
237	    result.evidence_summary = evidence.description.empty() ? "the supplied photo" : evidence.description.substr(0, match_at);
238	    result.confidence = 1.;
239	    // A correction names the current match, which already settled the model;
240	    // re-offering the touchscreen choice would discard the user's pick.
241	    if (match_at == std::string::npos && description.find("touchscreen") != std::string::npos) {
242	        static const std::array<std::string, 2> figma_models = {
243	            "creality ender-3 v2", "creality ender-3 v2 neo"
244	        };
245	        for (const std::string& wanted : figma_models) {
246	            const auto found = std::find_if(choices.begin(), choices.end(), [&](const PrinterCandidate* choice) {
247	                return choice && lowercase(choice->model_name) == wanted && choice->variant == "0.4";
248	            });
249	            if (found != choices.end()) result.candidate_ids.push_back((*found)->id);
250	        }
251	        if (result.candidate_ids.size() == 2)
252	            result.assumption = "Two Ender 3s have a touchscreen. The V2 has a knob under the screen; the Neo doesn’t.";
253	    }
254	    if (result.candidate_ids.empty() && !description.empty()) {
255	        // The longest named model wins, so "A1 mini" is not read as "A1";
256	        // within it a stated nozzle beats the standard one.
257	        const PrinterCandidate* stated = nullptr;
258	        const PrinterCandidate* standard = nullptr;
259	        for (const PrinterCandidate* choice : choices) {
260	            if (!choice || description.find(lowercase(choice->model_name)) == std::string::npos) continue;
261	            const PrinterCandidate* best = stated ? stated : standard;
262	            if (best && choice->model_name.size() < best->model_name.size()) continue;
263	            if (best && choice->model_name.size() > best->model_name.size()) stated = standard = nullptr;
264	            if (!stated && variant_text.find(choice->variant) != std::string::npos) stated = choice;
265	            if (!standard && choice->variant == "0.4") standard = choice;
266	        }
267	        if (const PrinterCandidate* chosen = stated ? stated : standard) {
268	            result.candidate_ids = {chosen->id};
269	            if (!correction.empty() && chosen != stated) result.unresolved_correction = correction;
270	        }
271	    }
272	    if (result.candidate_ids.empty()) {
273	        result.confidence = .5;
274	        std::vector<const PrinterCandidate*> distinct;
275	        std::map<std::string, std::size_t> model_indexes;
276	        for (const PrinterCandidate* choice : choices) {
277	            if (!choice) continue;
278	            const std::string model_key = choice->vendor_id + "\n" + choice->model_id;
279	            const auto [found, inserted] = model_indexes.emplace(model_key, distinct.size());
280	            if (inserted)
281	                distinct.push_back(choice);
282	            else if (choice->variant == "0.4" && distinct[found->second]->variant != "0.4")
283	                distinct[found->second] = choice;
284	        }
285	        const size_t count = std::min<size_t>(distinct.size(), 2);
286	        for (size_t i = 0; i < count; ++i)
287	            result.candidate_ids.push_back(distinct[i]->id);
288	    }
289	    if (result.candidate_ids.empty()) result.disposition = RecognitionDisposition::NoMatch;
290	    else if (result.candidate_ids.size() == 1) result.disposition = RecognitionDisposition::Recognized;
291	    else result.disposition = RecognitionDisposition::Ambiguous;
292	    if (result.assumption.empty())
293	        result.assumption = "The standard nozzle variant is selected unless the evidence names another size.";
294	    event.result = std::move(result);
295	    m_event = std::move(event);
296	    return true;
297	}
