19	std::string base64_encode(const std::string& input)
20	{
21	    static constexpr char table[] = "REDACTED/";
22	    std::string out;
23	    int value = 0;
24	    int bits = -6;
25	    for (unsigned char byte : input) {
26	        value = (value << 8) + byte;
27	        bits += 8;
28	        while (bits >= 0) {
29	            out.push_back(table[(value >> bits) & 0x3f]);
30	            bits -= 6;
31	        }
32	    }
33	    if (bits > -6)
34	        out.push_back(table[((value << 8) >> (bits + 8)) & 0x3f]);
35	    while (out.size() % 4)
36	        out.push_back('=');
37	    return out;
38	}
