40	json workspace_json(const Workspace::WorkspaceSnapshot& workspace)
41	{
42	    json plates = json::array();
43	    for (const auto& plate : workspace.plates) {
44	        json objects = json::array();
45	        for (const auto& object : plate.objects)
46	            objects.push_back(json{{"id", std::to_string(object.id.value())}, {"name", object.name},
47	                                   {"instances", object.instances.size()}});
48	        plates.push_back(json{{"id", std::to_string(plate.id.value())}, {"name", plate.name},
49	                              {"active", plate.active}, {"sliced", plate.sliced}, {"objects", std::move(objects)}});
50	    }
51	    json selected = json::array();
52	    for (const auto id : workspace.selected_objects)
53	        selected.push_back(std::to_string(id.value()));
54	    return json{{"sessionId", std::to_string(workspace.session.value())},
55	                {"revision", workspace.revision},
56	                {"projectName", workspace.setup.project_name},
57	                {"printerPreset", workspace.setup.printer_preset},
58	                {"filamentPreset", workspace.setup.filament_preset},
59	                {"selectedObjectIds", std::move(selected)},
60	                {"plates", std::move(plates)}};
61	}
