63	bool available_in_app(const ToolDefinition& definition, bool allow_import)
64	{
65	    return has_exposure(definition.exposure, ToolExposure::InApp) &&
66	           (definition.availability == ToolAvailability::Always || allow_import);
67	}
68	
69	bool has_closed_required_objects(const json& schema)
70	{
71	    if (schema.value("type", json()) == "object") {
72	        if (schema.value("additionalProperties", json()) != false)
73	            return false;
74	        const auto properties = schema.value("properties", json::object());
75	        const auto required = schema.value("required", json::array());
76	        for (const auto& property : properties.items())
77	            if (std::find(required.begin(), required.end(), property.key()) == required.end() ||
78	                !has_closed_required_objects(property.value()))
79	                return false;
80	    }
81	    return !schema.contains("items") || has_closed_required_objects(schema["items"]);
82	}
83	
84	json tools_for(bool allow_import)
85	{
86	    json tools = json::array();
87	    for (const ToolDefinition& definition : ToolRegistry::instance().definitions()) {
88	        if (!available_in_app(definition, allow_import))
89	            continue;
90	        tools.push_back(json{{"type", "function"},
91	                             {"name", definition.name},
92	                             {"description", definition.description},
93	                             // OpenAI strict mode cannot express optional
94	                             // fields or dynamic maps. Preserve the registry
95	                             // schema; native validation still owns acceptance.
96	                             {"strict", has_closed_required_objects(definition.input_schema)},
97	                             {"parameters", definition.input_schema}});
98	    }
99	    return tools;
100	}
