118	json OpenAIResponsesAgent::initial_input(const AgentRequest& request) const
119	{
120	    json input = json::array();
121	    for (const auto& message : request.conversation)
122	        input.push_back(json{{"role", message.role}, {"content", message.text}});
123	    if (request.purpose == AgentRequest::Purpose::ConversationTitle)
124	        return input;
125	
126	    json content = json::array();
127	    std::ostringstream context;
128	    context << request.user_text << "\n\nAuthoritative JusPrin workspace context:\n" << workspace_json(request.workspace).dump();
129	    for (const auto& attachment : request.attachments) {
130	        context << "\nAttachment " << attachment.id << ": " << attachment.name << " [" << attachment.kind << "]";
131	        if (!attachment.summary.empty())
132	            context << " — " << attachment.summary;
133	        if (!attachment.text.empty())
134	            context << "\n<attachment id=\"" << attachment.id << "\">\n" << attachment.text << "\n</attachment>";
135	    }
136	    content.push_back(json{{"type", "input_text"}, {"text", context.str()}});
137	    for (const auto& attachment : request.attachments) {
138	        if (attachment.bytes.empty())
139	            continue;
140	        const std::string mime = attachment.mime.empty() ? "application/octet-stream" : attachment.mime;
141	        const std::string data_url = "data:" + mime + ";base64," + base64_encode(attachment.bytes);
142	        if (attachment.kind == "image")
143	            content.push_back(json{{"type", "input_image"}, {"image_url", data_url}});
144	        else if (attachment.kind == "pdf")
145	            content.push_back(json{{"type", "input_file"}, {"filename", attachment.name}, {"file_data", data_url}});
146	    }
147	    input.push_back(json{{"role", "user"}, {"content", std::move(content)}});
148	    return input;
149	}
