167	bool OpenAIResponsesAgent::start(const AgentRequest& request)
168	{
169	    if (!ready() || m_busy)
170	        return false;
171	    m_input_history = json::array();
172	    m_pending_call_id.clear();
173	    m_waiting_for_tool = false;
174	    m_request_id = request.request_id;
175	    m_request_sequence = 0;
176	    m_title_request = request.purpose == AgentRequest::Purpose::ConversationTitle;
177	    m_allow_import = std::any_of(request.attachments.begin(), request.attachments.end(),
178	                                 [](const AgentAttachmentContext& attachment) { return attachment.importable; });
179	    return post(initial_input(request));
180	}
