182	bool OpenAIResponsesAgent::continue_after_tool(const AgentToolResult& result)
183	{
184	    if (!m_busy || !m_waiting_for_tool || result.call_id != m_pending_call_id)
185	        return false;
186	    json input = m_input_history;
187	    input.push_back(json{{"type", "function_call_output"}, {"call_id", result.call_id}, {"output", result.output_json}});
188	    m_waiting_for_tool = false;
189	    m_pending_call_id.clear();
190	    return post(std::move(input));
191	}
