193	bool OpenAIResponsesAgent::post(json input)
194	{
195	    m_sse_buffer.clear();
196	    m_terminal_seen = false;
197	    m_busy = true;
198	    AgentHttpRequest request;
199	    request.url = m_config.endpoint;
200	    request.authorization = "Bearer " + m_config.api_key;
201	    request.idempotency_key = m_request_id + "-request-" + std::to_string(++m_request_sequence);
202	    // store:false requests are stateless. Retain the complete turn input,
203	    // including user context and earlier tool results, for each continuation.
204	    m_input_history = input;
205	    request.body = request_body(std::move(input)).dump();
206	    const std::uint64_t generation = ++m_http_generation;
207	    if (!m_transport->post(std::move(request), [this, generation](AgentHttpEvent event) {
208	            accept_http(generation, std::move(event));
209	        })) {
210	        m_busy = false;
211	        return false;
212	    }
213	    return true;
214	}
