216	void OpenAIResponsesAgent::accept_http(std::uint64_t generation, AgentHttpEvent event)
217	{
218	    std::lock_guard<std::mutex> lock(m_mutex);
219	    m_http_events.push_back(QueuedHttpEvent{generation, std::move(event)});
220	}
