222	void OpenAIResponsesAgent::parse_sse_frame(const std::string& frame)
223	{
224	    std::string payload;
225	    std::istringstream lines(frame);
226	    std::string line;
227	    while (std::getline(lines, line)) {
228	        if (!line.empty() && line.back() == '\r')
229	            line.pop_back();
230	        if (line.rfind("data:", 0) == 0) {
231	            std::string part = line.substr(5);
232	            if (!part.empty() && part.front() == ' ')
233	                part.erase(part.begin());
234	            if (!payload.empty())
235	                payload += '\n';
236	            payload += part;
237	        }
238	    }
239	    if (payload.empty() || payload == "[DONE]")
240	        return;
241	    const json event = json::parse(payload, nullptr, false);
242	    if (!event.is_object()) {
243	        fail(AgentError{"malformed_response", "The Agent service returned an unreadable streaming response.", false});
244	        return;
245	    }
246	    const std::string type = event.value("type", "");
247	    if (std::getenv("JUSPRIN_AGENT_RECORD_USAGE") != nullptr &&
248	        (type == "response.completed" || type == "response.failed" || type == "response.incomplete" || type == "error"))
249	        std::cerr << "JUSPRIN LIVE EVENT type=" << (type.empty() ? "missing" : type) << '\n';
250	    if (type == "response.output_text.delta" && event.contains("delta") && event["delta"].is_string())
251	        m_events.push_back(AgentEvent::delta(event["delta"].get<std::string>()));
252	    else if (type == "response.completed" && event.contains("response"))
253	        finish_response(event["response"]);
254	    else if (type == "response.incomplete")
255	        fail(AgentError{"incomplete_response", "The Agent service stopped before finishing its response.", true});
256	    else if (type == "response.failed" || type == "error")
257	        fail(AgentError{"agent_service_error", "The Agent service could not complete the response.", true});
258	}
259	
260	void OpenAIResponsesAgent::finish_response(const json& response)
261	{
262	    if (m_terminal_seen)
263	        return;
264	    m_terminal_seen = true;
265	    if (!response.is_object() || !response.contains("output") || !response["output"].is_array()) {
266	        fail(AgentError{"malformed_response", "The Agent service response did not contain valid output.", false});
267	        return;
268	    }
269	    const auto& output = response["output"];
270	    m_input_history.insert(m_input_history.end(), output.begin(), output.end());
271	    if (m_config.usage_listener && response.contains("usage") && response["usage"].is_object()) {
272	        const json& usage = response["usage"];
273	        m_config.usage_listener(usage.value("input_tokens", std::uint64_t{0}),
274	                                usage.value("output_tokens", std::uint64_t{0}),
275	                                usage.value("total_tokens", std::uint64_t{0}));
276	    }
277	    for (const json& item : output) {
278	        if (!item.is_object() || item.value("type", "") != "function_call")
279	            continue;
280	        const std::string call_id = item.value("call_id", "");
281	        ToolRequest request{item.value("name", ""), item.value("arguments", "{}")};
282	        const ToolDefinition* definition = ToolRegistry::instance().find(request.tool);
283	        const bool available = !m_title_request && definition != nullptr && available_in_app(*definition, m_allow_import);
284	        ToolValidationResult validation;
285	        if (available)
286	            validation = ToolRegistry::instance().validate_call(*definition, request.arguments_json);
287	        if (call_id.empty() || !available || !validation.valid()) {
288	            fail(AgentError{"malformed_tool_call", "The Agent returned an invalid tool proposal.", false});
289	            return;
290	        }
291	        request.arguments_json = std::move(validation.arguments_json);
292	        m_pending_call_id = call_id;
293	        m_waiting_for_tool = true;
294	        AgentToolCall call{call_id, std::move(request), true};
295	        m_events.push_back(AgentEvent::tool_call(std::move(call)));
296	        return;
297	    }
298	    m_busy = false;
299	    m_events.push_back(AgentEvent::completed());
300	}
301	
302	void OpenAIResponsesAgent::parse_available()
303	{
304	    std::deque<QueuedHttpEvent> incoming;
305	    {
306	        std::lock_guard<std::mutex> lock(m_mutex);
307	        incoming.swap(m_http_events);
308	    }
309	    for (QueuedHttpEvent& queued : incoming) {
310	        if (queued.generation != m_http_generation)
311	            continue;
312	        AgentHttpEvent& event = queued.event;
313	        if (event.kind == AgentHttpEvent::Kind::Data) {
314	            m_sse_buffer += event.data;
315	            for (;;) {
316	                const std::size_t lf_pos = m_sse_buffer.find("\n\n");
317	                const std::size_t crlf_pos = m_sse_buffer.find("\r\n\r\n");
318	                const bool crlf_first = crlf_pos != std::string::npos &&
319	                                        (lf_pos == std::string::npos || crlf_pos < lf_pos);
320	                const std::size_t pos = crlf_first ? crlf_pos : lf_pos;
321	                if (pos == std::string::npos)
322	                    break;
323	                const std::string frame = m_sse_buffer.substr(0, pos);
324	                m_sse_buffer.erase(0, pos + (crlf_first ? 4 : 2));
325	                parse_sse_frame(frame);
326	            }
327	        } else if (event.kind == AgentHttpEvent::Kind::Error) {
328	            fail(http_error(event.status, event.error));
329	        } else if (!m_terminal_seen) {
330	            // A valid SSE stream may close immediately after its final data
331	            // line without a trailing blank-line delimiter. Consume that
332	            // complete residual frame before classifying the response.
333	            if (!m_sse_buffer.empty()) {
334	                parse_sse_frame(m_sse_buffer);
335	                m_sse_buffer.clear();
336	            }
337	            if (!m_terminal_seen)
338	                fail(AgentError{"malformed_response", "The Agent service ended before a complete response arrived.", true});
339	        }
340	    }
341	}
342	
343	std::optional<AgentEvent> OpenAIResponsesAgent::poll()
344	{
345	    parse_available();
346	    if (m_events.empty())
347	        return std::nullopt;
348	    AgentEvent event = std::move(m_events.front());
349	    m_events.pop_front();
350	    return event;
351	}
352	
353	AgentError OpenAIResponsesAgent::http_error(unsigned status, const std::string& detail) const
354	{
355	    if (status == 401 || status == 403)
356	        return {"invalid_credentials", "The OpenAI API key was rejected. Update the Agent configuration and try again.", false};
357	    if (status == 429)
358	        return {"rate_limited", "The OpenAI service is rate limited. Try again shortly.", true};
359	    if (status >= 500)
360	        return {"service_unavailable", "The OpenAI service is temporarily unavailable.", true};
361	    if (status == 408 || detail.find("timed out") != std::string::npos || detail.find("Timeout") != std::string::npos)
362	        return {"timeout", "The Agent request timed out.", true};
363	    return {"network_error", "The Agent request could not reach the OpenAI service.", true};
364	}
365	
366	void OpenAIResponsesAgent::fail(AgentError error)
367	{
368	    if (!m_busy && m_terminal_seen)
369	        return;
370	    m_busy = false;
371	    m_waiting_for_tool = false;
372	    m_terminal_seen = true;
373	    m_events.push_back(AgentEvent::failed(std::move(error)));
374	}
375	
376	void OpenAIResponsesAgent::cancel()
377	{
378	    if (m_transport)
379	        m_transport->cancel();
380	    ++m_http_generation;
381	    {
382	        std::lock_guard<std::mutex> lock(m_mutex);
383	        m_http_events.clear();
384	    }
385	    m_events.clear();
386	    m_sse_buffer.clear();
387	    m_busy = false;
388	    m_waiting_for_tool = false;
389	    m_terminal_seen = true;
390	}
