10	std::vector<DiscoveredPrinter> discover_printers()
11	{
12	    std::vector<DiscoveredPrinter> result;
13	    DeviceManager* devices = wxGetApp().getDeviceManager();
14	    if (!devices) return result;
15	    for (const auto& [id, machine] : devices->get_my_machine_list()) {
16	        if (!machine || (!machine->is_online() && !machine->is_connected())) continue;
17	        result.push_back({id, machine->get_dev_name(), machine->get_dev_ip(), machine->printer_type,
18	                          machine->connection_type(), true});
19	    }
20	    std::sort(result.begin(), result.end(), [](const DiscoveredPrinter& a, const DiscoveredPrinter& b) {
21	        if (a.connected != b.connected) return a.connected > b.connected;
22	        if (a.name != b.name) return a.name < b.name;
23	        return a.stable_id < b.stable_id;
24	    });
25	    return result;
26	}
