61	void show_printer_setup(wxWindow* owner, const ShellTheme& theme, bool dark, Plater& plater)
62	{
63	    PrinterCatalog catalog = PrinterCatalog::load(Slic3r::resources_dir());
64	    const bool use_mock = std::getenv("JUSPRIN_PRINTER_RECOGNITION_MOCK") != nullptr;
65	    OpenAIPrinterRecognitionConfig config;
66	    if (!use_mock && wxGetApp().app_config) {
67	        const std::string consent = wxGetApp().app_config->get("jusprin_agent", "cloud_consent");
68	        if (consent == "true" || consent == "1")
69	            config.api_key = Agent::load_provider_api_key("openai");
70	        const std::string model = wxGetApp().app_config->get("jusprin_agent", "model");
71	        if (!model.empty()) config.model = model;
72	    }
73	    if (const char* endpoint = std::getenv("JUSPRIN_OPENAI_ENDPOINT"); endpoint && *endpoint)
74	        config.endpoint = endpoint;
75	    std::unique_ptr<IPrinterRecognitionService> recognition;
76	    if (use_mock)
77	        recognition = std::make_unique<DeterministicPrinterRecognition>();
78	    else
79	        recognition = std::make_unique<OpenAIPrinterRecognition>(std::move(config),
80	                                                                  Agent::make_openai_http_transport());
81	    auto apply = [&plater](const PrinterCandidate& candidate, std::string& error) {
82	        return SetupCommands::install_and_select_printer(plater, candidate.vendor_id, candidate.model_id,
83	                                                         candidate.variant, candidate.default_material, error);
84	    };
85	    auto controller = std::make_unique<PrinterSetupController>(std::move(catalog), std::move(recognition),
86	                                                                std::move(apply));
87	    std::vector<DiscoveredPrinter> discovered = discover_printers();
88	    // Explicit developer scenarios make every handed-off Figma state
89	    // inspectable in an isolated app without a live API request or hardware.
90	    if (use_mock) {
91	        const std::string scenario = std::getenv("JUSPRIN_PRINTER_SETUP_SCENARIO")
92	            ? std::getenv("JUSPRIN_PRINTER_SETUP_SCENARIO") : "";
93	        if (scenario == "recognized" || scenario == "ambiguous") {
94	            PrinterEvidence evidence;
95	            evidence.description = scenario == "recognized"
96	                ? "Bambu Lab A1 mini" : "the ender with the touchscreen";
97	            controller->recognize(std::move(evidence));
98	            controller->poll();
99	        } else if (scenario == "network") {
100	            discovered = {{"01P00A3B", "Bambu Lab A1 mini", "192.0.2.2", "N1", "LAN", true}};
101	            controller->use_discovered(discovered.front());
102	        }
103	    }
104	    ModalScrim scrim(owner, theme.palette(dark), theme.metrics().printer_setup.scrim_alpha);
105	    PrinterSetupDialog dialog(scrim.owner_or(owner), theme, dark, std::move(controller), std::move(discovered));
106	    dialog.ShowModal();
107	}
