111	    // A missing token file or profile index is a packaging defect, not a state
112	    // this flow can recover from, so it propagates like it does from the
113	    // printer menu's entry point.
114	    const ShellTheme theme = ShellTheme::load_from_resources();
115	    show_printer_setup(owner, theme, dark, plater);
