16	// Lifecycle of one tool action. Pending awaits a user decision (or is
17	// auto-approved for read-only actions); Rejected, Cancelled, Succeeded, and
18	// Failed are terminal. A stale proposal fails with error code
19	// "stale_revision" rather than getting its own state.
20	enum class ToolState : std::uint8_t { Pending, Approved, Running, Succeeded, Failed, Cancelled, Rejected };
21	
22	constexpr bool tool_state_terminal(ToolState state)
23	{
24	    return state == ToolState::Succeeded || state == ToolState::Failed || state == ToolState::Cancelled ||
25	           state == ToolState::Rejected;
26	}
27	
28	// Approval classes from the handoff policy. ReadOnly actions do not change
29	// durable project or external state; Mutation actions durably change the
30	// project; Destructive actions revert, delete, overwrite, discard, print, or
31	// export.
32	enum class ActionClass : std::uint8_t { ReadOnly, Mutation, Destructive };
33	
34	// Assigned by the native adapter, never by untrusted tool arguments. External
35	// requests belong to the project, not to an in-app conversation message.
36	enum class ToolSource : std::uint8_t { Agent, Mcp };
37	
38	// The first production release asks for approval before every durable
39	// project mutation; read-only actions run without approval.
40	constexpr bool approval_required(ActionClass action_class)
41	{
42	    return action_class != ActionClass::ReadOnly;
43	}
44	
45	// Destructive actions always require action-time approval and must never use
46	// a remembered approval. (No remembered approvals exist in this release; the
47	// policy still records which class may ever gain them.)
48	constexpr bool remembered_approval_allowed(ActionClass action_class)
49	{
50	    return action_class == ActionClass::Mutation;
51	}
