43	TEST_CASE("printer recognition uses a stateless strict Responses request", "[printer-recognition]")
44	{
45	    auto transport = std::make_unique<FakeTransport>();
46	    auto* fake = transport.get();
47	    OpenAIPrinterRecognition service({"secret", "test-model", "https://example.invalid/responses"},
48	                                     std::move(transport));
49	    const PrinterCandidate local = candidate();
50	    REQUIRE(service.start(7, {"small Bambu", "image", "image/png", "printer.png"}, {&local}));
51	    const auto body = nlohmann::json::parse(fake->last.body);
52	    CHECK(body.at("store") == false);
53	    CHECK(body.at("model") == "test-model");
54	    CHECK(body.at("max_output_tokens") == 512);
55	    CHECK(body.at("text").at("format").at("type") == "json_schema");
56	    CHECK(body.at("text").at("format").at("strict") == true);
57	    CHECK(body.at("text").at("format").at("schema").at("additionalProperties") == false);
58	    CHECK(body.at("text").at("format").at("schema").at("properties").at("candidate_ids").at("maxItems") == 3);
59	    const auto& required = body.at("text").at("format").at("schema").at("required");
60	    CHECK(std::find(required.begin(), required.end(), "confidence") != required.end());
61	    CHECK(std::find(required.begin(), required.end(), "unresolved_correction") != required.end());
62	    const auto& content = body.at("input").front().at("content");
63	    REQUIRE(content.size() == 2);
64	    CHECK(content.back().at("image_url").get<std::string>().rfind("data:image/png;base64,", 0) == 0);
65	    const auto prompt = content.front().at("text").get<std::string>();
66	    CHECK(prompt.find("\"default_variant\":true") != std::string::npos);
67	    CHECK(fake->last.authorization == "Bearer secret");
68	    CHECK(fake->last.response_size_limit == 2u * 1024u * 1024u);
69	
70	    const nlohmann::json recognized = {{"disposition", "recognized"}, {"candidate_ids", {"local-a1"}},
71	                                       {"evidence_summary", "A1 mini"}, {"assumption", "0.4 mm nozzle"},
72	                                       {"confidence", 0.92}, {"unresolved_correction", "AMS"}};
73	    const nlohmann::json response = {{"output", {{{"content", {{{"type", "output_text"},
74	                                                                   {"text", recognized.dump()}}}}}}}};
75	    fake->callback({Agent::AgentHttpEvent::Kind::Data, response.dump(), {}, 200});
76	    fake->callback({Agent::AgentHttpEvent::Kind::Complete, {}, {}, 200});
77	    const auto event = service.poll();
78	    REQUIRE(event);
79	    REQUIRE(event->result);
80	    CHECK(event->generation == 7);
81	    CHECK(event->result->candidate_ids == std::vector<std::string>{"local-a1"});
82	    CHECK(event->result->confidence == Catch::Approx(0.92));
83	    CHECK(event->result->unresolved_correction == "AMS");
