15	class FakeRecognition final : public IPrinterRecognitionService
16	{
17	public:
18	    bool ready() const override { return available; }
19	    bool start(std::uint64_t generation, const PrinterEvidence& evidence,
20	               const std::vector<const PrinterCandidate*>& choices) override
21	    {
22	        last_generation = generation;
23	        last_evidence = evidence;
24	        ++starts_seen;
25	        offered.clear();
26	        for (const auto* choice : choices) offered.push_back(choice->id);
27	        return starts;
28	    }
29	    void cancel() override { ++cancels; }
30	    std::optional<RecognitionEvent> poll() override
31	    {
32	        if (events.empty()) return std::nullopt;
33	        auto event = events.front(); events.pop_front(); return event;
34	    }
35	    bool available{true};
36	    bool starts{true};
37	    int cancels{0};
38	    int starts_seen{0};
39	    PrinterEvidence last_evidence;
40	    std::uint64_t last_generation{0};
41	    std::vector<std::string> offered;
42	    std::deque<RecognitionEvent> events;
43	};
