14	std::string base64_encode(const std::string& input)
15	{
16	    static constexpr char table[] = "REDACTED/";
17	    std::string out;
18	    int value = 0;
19	    int bits = -6;
20	    for (unsigned char byte : input) {
21	        value = (value << 8) + byte;
22	        bits += 8;
23	        while (bits >= 0) { out.push_back(table[(value >> bits) & 0x3f]); bits -= 6; }
24	    }
25	    if (bits > -6) out.push_back(table[((value << 8) >> (bits + 8)) & 0x3f]);
26	    while (out.size() % 4) out.push_back('=');
27	    return out;
28	}
29	
30	std::string response_text(const json& response)
31	{
32	    if (response.contains("output_text") && response["output_text"].is_string())
33	        return response["output_text"].get<std::string>();
34	    for (const auto& output : response.value("output", json::array()))
35	        for (const auto& content : output.value("content", json::array()))
36	            if (content.value("type", "") == "output_text" && content.contains("text") && content["text"].is_string())
37	                return content["text"].get<std::string>();
38	    return {};
39	}
40	
41	RecognitionError http_error(unsigned status)
42	{
43	    if (status == 401 || status == 403)
44	        return {"authentication", "OpenAI could not authenticate the configured API key.", false};
45	    if (status == 429)
46	        return {"rate_limit", "OpenAI is busy or the configured account has reached its limit. Try again.", true};
47	    if (status >= 500)
48	        return {"provider", "OpenAI could not recognize the printer right now. Try again.", true};
49	    return {"request", "The printer recognition request was rejected.", false};
50	}
