148	
149	RecognitionEvent OpenAIPrinterRecognition::parse(std::uint64_t generation, unsigned status,
150	                                                 const std::string& body) const
151	{
152	    RecognitionEvent event;
153	    event.generation = generation;
154	    if (status < 200 || status >= 300) { event.error = http_error(status); return event; }
155	    const json response = json::parse(body, nullptr, false);
156	    if (!response.is_object()) {
157	        event.error = RecognitionError{"malformed_response", "OpenAI returned an unreadable response.", true};
158	        return event;
159	    }
160	    const json recognized = json::parse(response_text(response), nullptr, false);
161	    if (!recognized.is_object()) {
162	        event.error = RecognitionError{"malformed_response", "OpenAI returned an unreadable recognition result.", true};
163	        return event;
164	    }
165	    RecognitionResult result;
166	    const std::string disposition = recognized.value("disposition", "no_match");
167	    result.disposition = disposition == "recognized" ? RecognitionDisposition::Recognized
168	                       : disposition == "ambiguous" ? RecognitionDisposition::Ambiguous
169	                                                    : RecognitionDisposition::NoMatch;
170	    if (recognized.contains("candidate_ids") && recognized["candidate_ids"].is_array())
171	        for (const auto& id : recognized["candidate_ids"])
172	            if (id.is_string()) result.candidate_ids.push_back(id.get<std::string>());
173	    result.evidence_summary = recognized.value("evidence_summary", "");
174	    result.assumption = recognized.value("assumption", "");
175	    // A missing confidence reads as uncertain, never as certain.
176	    if (recognized.contains("confidence") && recognized["confidence"].is_number())
177	        result.confidence = recognized["confidence"].get<double>();
178	    result.unresolved_correction = recognized.value("unresolved_correction", "");
179	    event.result = std::move(result);
180	    return event;
181	}
182	
183	std::optional<RecognitionEvent> OpenAIPrinterRecognition::poll()
184	{
185	    std::deque<HttpItem> incoming;
186	    {
187	        std::lock_guard<std::mutex> lock(m_mutex);
188	        incoming.swap(m_http);
189	    }
190	    for (HttpItem& item : incoming) {
191	        if (!m_busy || item.generation != m_generation) continue;
192	        if (item.event.kind == Agent::AgentHttpEvent::Kind::Data) m_body += item.event.data;
193	        else if (item.event.kind == Agent::AgentHttpEvent::Kind::Error) {
194	            m_busy = false;
195	            RecognitionEvent failure;
196	            failure.generation = item.generation;
197	            failure.error = item.event.status ? http_error(item.event.status)
198	                : RecognitionError{"network", "Could not reach OpenAI. Check the connection and try again.", true};
199	            m_events.push_back(std::move(failure));
200	        } else {
201	            m_busy = false;
202	            m_events.push_back(parse(item.generation, item.event.status, m_body));
203	        }
204	    }
205	    if (m_events.empty()) return std::nullopt;
206	    RecognitionEvent event = std::move(m_events.front());
207	    m_events.pop_front();
208	    return event;
209	}
