65	void PrinterSetupController::accept(const RecognitionEvent& event)
66	{
67	    if (event.generation != m_generation || m_state != FlowState::Recognizing) return;
68	    if (event.error) {
69	        fail(event.error->message, event.error->retryable);
70	        return;
71	    }
72	    if (!event.result) return;
73	    std::set<std::string> seen;
74	    for (const std::string& id : event.result->candidate_ids) {
75	        if (!seen.insert(id).second) continue;
76	        if (!m_allowed_candidate_ids.count(id)) continue;
77	        if (const PrinterCandidate* candidate = m_catalog.find(id)) m_candidates.push_back(candidate);
78	    }
79	    m_evidence_summary = event.result->evidence_summary;
80	    m_assumption = event.result->assumption;
81	    m_unresolved_correction = event.result->unresolved_correction;
82	    const RecognitionDisposition disposition = event.result->disposition;
83	    if (disposition == RecognitionDisposition::Recognized && m_candidates.size() == 1 &&
84	        event.result->confidence >= kRecognitionConfidenceThreshold) {
85	        m_state = FlowState::Recognized;
86	    } else if ((disposition == RecognitionDisposition::Ambiguous && m_candidates.size() >= 2) ||
87	               (disposition != RecognitionDisposition::NoMatch && m_candidates.size() == 1)) {
88	        // One surviving candidate here is either a low-confidence
89	        // identification or an ambiguous answer whose other IDs failed
90	        // validation. Either way the user chooses; nothing is presumed.
91	        m_uncertain = m_candidates.size() == 1;
92	        m_state = FlowState::Ambiguous;
93	    } else {
94	        m_candidates.clear();
95	        fail("That evidence did not match a supported printer profile. Add a clearer description or photo, or set it up manually.", false);
96	    }
97	}
98	
99	bool PrinterSetupController::use_discovered(const DiscoveredPrinter& printer)
100	{
101	    const PrinterCandidate* candidate = m_catalog.find_device_model(printer.device_model_id);
102	    if (!candidate) {
103	        fail("The network printer was found, but its model does not match a supported local profile.", false);
104	        return false;
105	    }
106	    if (m_recognition) m_recognition->cancel();
107	    ++m_generation;
108	    m_evidence = {};
109	    m_evidence.discovered_device = printer;
110	    m_allowed_candidate_ids.clear();
111	    m_candidates = {candidate};
112	    m_evidence_summary = printer.name;
113	    m_assumption = printer.connection.empty() ? "Found on the local network."
114	                                               : "Connected · " + printer.connection;
115	    m_error.clear();
116	    m_retryable = false;
117	    m_apply_failed = false;
118	    m_uncertain = false;
119	    m_unresolved_correction.clear();
120	    m_state = FlowState::Recognized;
121	    return true;
122	}
123	
124	bool PrinterSetupController::choose(const std::string& candidate_id)
125	{
126	    if (m_state != FlowState::Ambiguous) return false;
127	    const auto found = std::find_if(m_candidates.begin(), m_candidates.end(), [&](const PrinterCandidate* candidate) {
128	        return candidate && candidate->id == candidate_id;
129	    });
130	    if (found == m_candidates.end()) return false;
131	    const PrinterCandidate* candidate = *found;
132	    m_candidates = {candidate};
133	    m_uncertain = false;
134	    m_state = FlowState::Recognized;
135	    return true;
136	}
137	
138	bool PrinterSetupController::correct(const std::string& correction)
139	{
140	    if (m_state != FlowState::Recognized || m_candidates.size() != 1 || correction.empty()) return false;
141	    const PrinterCandidate& current = *m_candidates.front();
142	    PrinterEvidence evidence = m_evidence;
143	    // A second correction replaces the first rather than stacking on it.
144	    if (const auto marker = evidence.description.find(kCurrentMatchMarker); marker != std::string::npos)
145	        evidence.description.resize(marker);
146	    evidence.description += kCurrentMatchMarker + current.model_name + " " + current.variant +
147	                            " mm nozzle\nCorrection: " + correction;
148	    return recognize(std::move(evidence));
149	}
150	
151	bool PrinterSetupController::clarify(const std::string& detail)
152	{
153	    if (m_state != FlowState::Ambiguous || detail.empty()) return false;
154	    PrinterEvidence evidence = m_evidence;
155	    if (!evidence.description.empty()) evidence.description += "\n";
156	    evidence.description += detail;
157	    return recognize(std::move(evidence));
158	}
159	
160	bool PrinterSetupController::confirm()
161	{
162	    if (m_state != FlowState::Recognized || m_candidates.size() != 1 || !m_apply) return false;
163	    std::string error;
164	    if (!m_apply(*m_candidates.front(), error)) {
165	        fail(error.empty() ? "The printer setup could not be applied. Your previous setup is unchanged." : error, true);
166	        m_apply_failed = true;
167	        return false;
168	    }
169	    m_state = FlowState::Complete;
170	    return true;
171	}
172	
173	bool PrinterSetupController::retry()
174	{
175	    if (m_state != FlowState::Error || !m_retryable) return false;
176	    if (m_apply_failed) {
177	        // The validated candidate is still held; only the apply step failed.
178	        m_apply_failed = false;
179	        m_error.clear();
180	        m_retryable = false;
181	        m_state = FlowState::Recognized;
182	        return true;
183	    }
184	    return recognize(m_evidence);
185	}
186	
187	void PrinterSetupController::start_over()
188	{
189	    if (m_recognition) m_recognition->cancel();
190	    ++m_generation;
191	    m_state = FlowState::Initial;
192	    m_evidence = {};
193	    m_candidates.clear();
194	    m_allowed_candidate_ids.clear();
195	    m_evidence_summary.clear();
196	    m_assumption.clear();
197	    m_error.clear();
198	    m_retryable = false;
199	    m_apply_failed = false;
200	    m_uncertain = false;
201	    m_unresolved_correction.clear();
202	}
