31	std::vector<std::string> split(const std::string& value, char delimiter)
32	{
33	    std::vector<std::string> result;
34	    std::istringstream input(value);
35	    std::string part;
36	    while (std::getline(input, part, delimiter))
37	        if (!part.empty()) result.push_back(part);
38	    return result;
39	}
