48	std::set<std::string> words(const std::string& value)
49	{
50	    std::set<std::string> result;
51	    std::string word;
52	    for (unsigned char c : lower(value)) {
53	        if (std::isalnum(c)) word.push_back(char(c));
54	        else if (word.size() > 1) { result.insert(word); word.clear(); }
55	        else word.clear();
56	    }
57	    if (word.size() > 1) result.insert(word);
58	    return result;
59	}
