69	json resolve_machine(const std::string& name, const std::map<std::string, json>& machines,
70	                     std::set<std::string>& visiting)
71	{
72	    const auto found = machines.find(name);
73	    if (found == machines.end() || !visiting.insert(name).second)
74	        return json::object();
75	    json resolved = json::object();
76	    const std::string parent = found->second.value("inherits", "");
77	    if (!parent.empty())
78	        resolved = resolve_machine(parent, machines, visiting);
79	    for (const auto& item : found->second.items())
80	        resolved[item.key()] = item.value();
81	    visiting.erase(name);
82	    return resolved;
83	}
