85	std::string build_volume(const json& machine)
86	{
87	    const auto area = machine.value("printable_area", json::array());
88	    double min_x = 0., min_y = 0., max_x = 0., max_y = 0.;
89	    bool first = true;
90	    for (const auto& point : area) {
91	        if (!point.is_string()) continue;
92	        const auto values = split(point.get<std::string>(), 'x');
93	        if (values.size() != 2) continue;
94	        try {
95	            const double x = std::stod(values[0]);
96	            const double y = std::stod(values[1]);
97	            if (first) { min_x = max_x = x; min_y = max_y = y; first = false; }
98	            else { min_x = std::min(min_x, x); max_x = std::max(max_x, x);
99	                   min_y = std::min(min_y, y); max_y = std::max(max_y, y); }
100	        } catch (const std::exception&) {}
101	    }
102	    if (first) return {};
103	    const std::string height = first_string(machine.value("printable_height", json()));
104	    if (height.empty()) return {};
105	    auto clean = [](double value) {
106	        std::ostringstream out;
107	        out << std::fixed << std::setprecision(value == std::floor(value) ? 0 : 1) << value;
108	        return out.str();
109	    };
110	    return clean(max_x - min_x) + " × " + clean(max_y - min_y) + " × " + height + " mm";
111	}
