117	PrinterCatalog PrinterCatalog::load(const std::string& resources_directory)
118	{
119	    const fs::path profiles = fs::path(resources_directory) / "profiles";
120	    std::vector<PrinterCandidate> candidates;
121	    for (const fs::directory_entry& vendor_entry : fs::directory_iterator(profiles)) {
122	        if (!vendor_entry.is_regular_file() || vendor_entry.path().extension() != ".json") continue;
123	        const std::string vendor_id = vendor_entry.path().stem().string();
124	        const json index = read_json(vendor_entry.path());
125	        if (!index.contains("machine_model_list") || !index.contains("machine_list")) continue;
126	        const std::string vendor_name = index.value("name", vendor_id);
127	        const fs::path vendor_dir = profiles / vendor_id;
128	
129	        std::map<std::string, json> machines;
130	        for (const auto& entry : index["machine_list"]) {
131	            const std::string name = entry.value("name", "");
132	            const std::string sub_path = entry.value("sub_path", "");
133	            if (!name.empty() && !sub_path.empty()) machines.emplace(name, read_json(vendor_dir / sub_path));
134	        }
135	
136	        for (const auto& entry : index["machine_model_list"]) {
137	            const std::string sub_path = entry.value("sub_path", "");
138	            if (sub_path.empty()) continue;
139	            const json model = read_json(vendor_dir / sub_path);
140	            const std::string model_name = model.value("name", entry.value("name", ""));
141	            const std::string model_id = model_name;
142	            const std::string device_model = model.value("model_id", "");
143	            const auto variants = split(first_string(model.value("nozzle_diameter", json())), ';');
144	            const auto materials = split(first_string(model.value("default_materials", json())), ';');
145	            const std::string plate = first_string(model.value("default_bed_type", json()));
146	            fs::path artwork = vendor_dir / (model_name + "_cover.png");
147	            if (!fs::exists(artwork)) artwork.clear();
148	
149	            for (const std::string& variant : variants) {
150	                const std::string preset_name = model_name + " " + variant + " nozzle";
151	                std::set<std::string> visiting;
152	                const json machine = resolve_machine(preset_name, machines, visiting);
153	                if (machine.empty()) continue; // not an installable variant
154	                PrinterCandidate candidate;
155	                candidate.id = "printer-" + std::to_string(candidates.size());
156	                candidate.vendor_id = vendor_id;
157	                candidate.vendor_name = vendor_name;
158	                candidate.model_id = model_id;
159	                candidate.model_name = model_name;
160	                candidate.device_model_id = device_model;
161	                candidate.variant = variant;
162	                candidate.preset_name = preset_name;
163	                candidate.build_volume = build_volume(machine);
164	                candidate.default_material = !materials.empty() ? materials.front()
165	                    : first_string(machine.value("default_filament_profile", json()));
166	                candidate.default_plate = plate;
167	                candidate.artwork_path = artwork.string();
168	                candidates.push_back(std::move(candidate));
169	            }
170	        }
171	    }
172	    if (candidates.empty())
173	        throw std::runtime_error("No installable printer profiles were found.");
174	    return PrinterCatalog(std::move(candidates));
175	}
