196	std::vector<const PrinterCandidate*> PrinterCatalog::recognition_choices(const PrinterEvidence& evidence) const
197	{
198	    struct Scored { const PrinterCandidate* candidate; int score; };
199	    const auto evidence_words = words(evidence.description);
200	    std::vector<Scored> scored;
201	    scored.reserve(m_candidates.size());
202	    for (const PrinterCandidate& candidate : m_candidates) {
203	        int score = 0;
204	        const auto candidate_words = words(candidate.vendor_name + " " + candidate.model_name + " " + candidate.variant);
205	        for (const std::string& word : evidence_words)
206	            if (candidate_words.count(word)) score += word.size() >= 4 ? 3 : 1;
207	        if (!evidence.description.empty() && lower(evidence.description).find(lower(candidate.model_name)) != std::string::npos)
208	            score += 20;
209	        scored.push_back({&candidate, score});
210	    }
211	    std::stable_sort(scored.begin(), scored.end(), [](const Scored& a, const Scored& b) { return a.score > b.score; });
212	
213	    std::vector<const PrinterCandidate*> result;
214	    std::set<std::string> models;
215	    const bool has_text_match = !scored.empty() && scored.front().score > 0;
216	    for (const Scored& item : scored) {
217	        if (has_text_match) {
218	            if (item.score == 0 || result.size() >= 60) break;
219	            result.push_back(item.candidate);
220	        } else if (models.insert(item.candidate->vendor_id + "\n" + item.candidate->model_id).second) {
221	            result.push_back(item.candidate);
222	            if (result.size() >= 400) break;
223	        }
224	    }
225	    return result;
226	}
