    std::set<std::string> offered;
    for (const PrinterCandidate* model : models) offered.insert(model->vendor_id + "\n" + model->model_id);
    std::set<std::string> shipped;
    for (const PrinterCandidate& candidate : catalog.candidates()) shipped.insert(candidate.vendor_id + "\n" + candidate.model_id);
