std::vector<const PrinterCandidate*> models() const;
// The installable variant of `model` with this nozzle diameter, or null.
// "0.6", "0.60" and "0.6 mm" name the same nozzle.
const PrinterCandidate* variant(const PrinterCandidate& model, const std::string& nozzle_mm) const;

// "0.60 mm" -> "0.6", ".6" -> "0.6". Text rather than a parsed double, so the
// comparison does not depend on the process's numeric locale.
std::string nozzle_key(const std::string& value)
{
    std::string key;
    for (char c : value) {
        if ((c < '0' || c > '9') && c != '.') break;
        key.push_back(c);
    }
    if (key.find('.') != std::string::npos) {
        while (!key.empty() && key.back() == '0') key.pop_back();
        if (!key.empty() && key.back() == '.') key.pop_back();
    }
    if (!key.empty() && key.front() == '.') key.insert(key.begin(), '0');
    return key;
}

    return result;
}

const PrinterCandidate* PrinterCatalog::variant(const PrinterCandidate& model, const std::string& nozzle_mm) const
{
    const std::string wanted = nozzle_key(nozzle_mm);
    if (wanted.empty()) return nullptr;
    const auto found = std::find_if(m_candidates.begin(), m_candidates.end(), [&](const PrinterCandidate& item) {
        return item.vendor_id == model.vendor_id && item.model_id == model.model_id && nozzle_key(item.variant) == wanted;
    });
    return found == m_candidates.end() ? nullptr : &*found;
}

