TEST_CASE("recognition is offered every packaged model once, at its standard nozzle", "[printer-setup]")
{
    const PrinterCatalog catalog = PrinterCatalog::load(std::string(JUSPRIN_SOURCE_DIR) + "/resources");
    const auto models = catalog.models();
    std::set<std::string> offered;
    for (const PrinterCandidate* model : models) offered.insert(model->vendor_id + "\n" + model->model_id);
    std::set<std::string> shipped;
    for (const PrinterCandidate& candidate : catalog.candidates()) shipped.insert(candidate.vendor_id + "\n" + candidate.model_id);
    CHECK(offered.size() == models.size());
    CHECK(offered == shipped);
    const auto a1 = std::find_if(models.begin(), models.end(), [](const PrinterCandidate* model) {
        return model->model_name == "Bambu Lab A1 mini";
    });
    REQUIRE(a1 != models.end());
    CHECK((*a1)->variant == "0.4");
}

TEST_CASE("a nozzle size resolves to that model's shipped variant", "[printer-setup]")
{
    const PrinterCatalog catalog(fixtures());
    const PrinterCandidate& a1 = *catalog.find("a1");
    REQUIRE(catalog.variant(a1, "0.6"));
    CHECK(catalog.variant(a1, "0.6")->id == "a1-06");
    CHECK(catalog.variant(a1, "0.60 mm")->id == "a1-06");
    CHECK(catalog.variant(a1, "0.4")->id == "a1");
    CHECK(catalog.variant(a1, "") == nullptr);
    CHECK(catalog.variant(a1, "0.8") == nullptr);
    CHECK(catalog.variant(*catalog.find("v2"), "0.6") == nullptr);
    const auto models = catalog.models();
    REQUIRE(models.size() == 3);
    CHECK(models.front()->id == "a1");
}

TEST_CASE("a stated nozzle the model does not ship keeps the standard variant and is not applied", "[printer-setup]")
{
    auto recognition = std::make_unique<FakeRecognition>();
    auto* fake = recognition.get();
    std::string applied;
    PrinterSetupController controller(PrinterCatalog(fixtures()), std::move(recognition),
        [&](const PrinterCandidate& candidate, std::string&) { applied = candidate.id; return true; });

    SECTION("recognized") {
        REQUIRE(controller.recognize(described("Ender-3 V2 with a 0.6 nozzle")));
        fake->events.push_back(result_event(fake->last_generation, RecognitionDisposition::Recognized, {"v2"}, {}, "0.6"));
        controller.poll();
        REQUIRE(controller.state() == FlowState::Recognized);
        CHECK(controller.candidates().front()->id == "v2");
        CHECK(controller.unresolved_correction() == "0.6 mm nozzle");
        REQUIRE(controller.confirm());
        CHECK(applied == "v2");
    }
    SECTION("alongside another unrepresentable part") {
        REQUIRE(controller.recognize(described("Ender-3 V2, 0.6 nozzle, AMS")));
        fake->events.push_back(result_event(fake->last_generation, RecognitionDisposition::Recognized, {"v2"}, "AMS", "0.6"));
        controller.poll();
        REQUIRE(controller.state() == FlowState::Recognized);
        CHECK(controller.unresolved_correction() == "0.6 mm nozzle, AMS");
    }
    SECTION("chosen from an ambiguous answer") {
        REQUIRE(controller.recognize(described("a 0.6 nozzle printer")));
        fake->events.push_back(result_event(fake->last_generation, RecognitionDisposition::Ambiguous, {"a1", "v2"}, {}, "0.6"));
        controller.poll();
        REQUIRE(controller.state() == FlowState::Ambiguous);
        REQUIRE(controller.candidates().size() == 2);
        CHECK(controller.candidates()[0]->id == "a1-06");
        CHECK(controller.candidates()[1]->id == "v2");
        CHECK(controller.unresolved_correction().empty());
        REQUIRE(controller.choose("v2"));
        CHECK(controller.unresolved_correction() == "0.6 mm nozzle");
    }
}

